// Package demo is the fictional world the app runs on locally and in
// tests: a season of invented clubs, players and results in FPL Draft's
// JSON shapes (generated by tools/genworld, embedded here), served through
// the real FPL client with a DirTransport, so nothing ever calls FPL.
//
// Seed loads it into any set of repositories (Postgres for cmd/seed,
// memory for tests and the database-less dev server) and creates a demo
// league that has drafted and played gameweeks 1 to 7.
//
// data/element-summary holds invented previous seasons (history_past) for
// four players, written by hand rather than by genworld; like FPL they
// send 0 for stats not tracked in a season.
package demo

import (
	"cmp"
	"context"
	"embed"
	"fmt"
	"io/fs"
	"log/slog"
	"slices"
	"time"

	"github.com/aatrey56/myfantasyprem/server/internal/auth"
	"github.com/aatrey56/myfantasyprem/server/internal/history"
	"github.com/aatrey56/myfantasyprem/server/internal/league"
	"github.com/aatrey56/myfantasyprem/server/internal/poller"
	"github.com/aatrey56/myfantasyprem/server/internal/provider/fpl"
	"github.com/aatrey56/myfantasyprem/server/internal/scoring"
	"github.com/aatrey56/myfantasyprem/server/internal/stats"
)

//go:embed data
var data embed.FS

// ProviderName namespaces the demo's external ids, so a database seeded
// with the demo never confuses its players with real FPL ones.
const ProviderName = "demo"

// LeagueName is the seeded league.
const LeagueName = "The Sunday Draft"

// DemoEmail is the account to sign in with locally (magic link).
const DemoEmail = "demo@myfantasyprem.test"

// Managers of the demo league, the demo account first (commissioner).
var Managers = []struct{ Name, Email, Team string }{
	{"Sam Parker", DemoEmail, "Sunday League Heroes"},
	{"Priya N.", "priya@myfantasyprem.test", "Gaffer's Army"},
	{"Olu A.", "olu@myfantasyprem.test", "Expected Toulouse"},
	{"Jess K.", "jess@myfantasyprem.test", "Net Busters"},
	{"Marco R.", "marco@myfantasyprem.test", "Park the Bus"},
	{"Hannah L.", "hannah@myfantasyprem.test", "Clean Sheet Club"},
	{"Dev S.", "dev@myfantasyprem.test", "Bench Warmers"},
	{"Tomas G.", "tomas@myfantasyprem.test", "Late Winners"},
	{"Ellie W.", "ellie@myfantasyprem.test", "Top Bins"},
}

// FS returns the demo data in FPL's API layout (bootstrap-static.json,
// event/{gw}/live.json, game.json, pl/event-status.json).
//
// The recordings had no `starts`; it was added to each live.json by one
// rule: a player started a fixture when he played 60 minutes or more in
// it (the minutes line of that fixture's explain), so starts is the count
// of such fixtures, 0 without any.
func FS() fs.FS {
	sub, err := fs.Sub(data, "data")
	if err != nil {
		panic(err)
	}
	return sub
}

// Source returns an FPL client that reads the demo data instead of the
// network.
func Source(log *slog.Logger) *fpl.Client {
	return fpl.New(fpl.Options{Transport: fpl.DirTransport{FS: FS()}, Logger: log, MinInterval: -1})
}

// Deps are the repositories Seed writes.
type Deps struct {
	Auth    auth.Service
	Leagues *league.Service
	Stats   stats.Repo
	// History, when set, gets the demo players' previous seasons.
	History history.Store
	Log     *slog.Logger
	Now     func() time.Time
}

// Result describes the seeded data.
type Result struct {
	LeagueID string
	UserIDs  []string // in Managers order
	Gameweek int
}

// Seed ingests the demo season and creates the demo league with its
// managers, draft, lineups and schedule, then scores every played
// gameweek. It is idempotent: a second run refreshes the stats and
// rescores, and reuses the existing league.
func Seed(ctx context.Context, d Deps) (Result, error) {
	if d.Log == nil {
		d.Log = slog.Default()
	}
	if d.Now == nil {
		d.Now = time.Now
	}
	var res Result
	gw, err := LoadStats(ctx, d.Stats, d.Log, d.Now)
	if err != nil {
		return res, err
	}
	res.Gameweek = gw

	for _, m := range Managers {
		u, err := d.Auth.CreateUser(ctx, m.Name, m.Email)
		if err != nil {
			return res, err
		}
		res.UserIDs = append(res.UserIDs, u.ID)
	}
	commish := res.UserIDs[0]
	mine, err := d.Leagues.ForUser(ctx, commish)
	if err != nil {
		return res, err
	}
	for _, l := range mine {
		if l.Name == LeagueName && l.CommissionerID == commish {
			res.LeagueID = l.ID
		}
	}
	if res.LeagueID == "" {
		if res.LeagueID, err = createLeague(ctx, d, res.UserIDs); err != nil {
			return res, err
		}
	}

	if d.History != nil {
		if err := LoadHistory(ctx, d.History, d.Log, d.Now); err != nil {
			return res, err
		}
	}

	sc := &league.Scorer{Leagues: d.Leagues.Repo(), Stats: d.Stats, Rules: scoring.StandardLineup(), Log: d.Log}
	for gw := 1; gw <= res.Gameweek; gw++ {
		if _, err := sc.Recompute(ctx, gw, nil, true); err != nil {
			return res, err
		}
	}

	// Record the seed as a good poll so meta reflects it; a running poller
	// takes over from here.
	d.Log.InfoContext(ctx, "demo seeded", "league", res.LeagueID, "gameweek", res.Gameweek, "managers", len(res.UserIDs))
	return res, nil
}

// LoadStats ingests the demo season (every played gameweek) into repo and
// records it as a good poll. It returns the current gameweek. Tests use it
// for a world without the demo league.
func LoadStats(ctx context.Context, repo stats.Repo, log *slog.Logger, now func() time.Time) (int, error) {
	if log == nil {
		log = slog.Default()
	}
	if now == nil {
		now = time.Now
	}
	src := Source(log)
	in := stats.NewIngester(repo, ProviderName, now)
	b, err := src.Bootstrap(ctx)
	if err != nil {
		return 0, err
	}
	fixtures, err := src.Fixtures(ctx)
	if err != nil {
		return 0, err
	}
	st, err := src.GameweekStatus(ctx)
	if err != nil {
		return 0, err
	}
	if err := in.Season(ctx, b, fixtures, st); err != nil {
		return 0, err
	}
	for gw := 1; gw <= st.Current; gw++ {
		live, err := src.EventLive(ctx, gw)
		if err != nil {
			return 0, err
		}
		if _, err := in.Live(ctx, live, st); err != nil {
			return 0, fmt.Errorf("demo: gameweek %d: %w", gw, err)
		}
	}
	// Record the load as a good poll so meta reflects it; a running poller
	// takes over from here.
	w, err := league.LoadWorld(ctx, repo, st.Current)
	if err != nil {
		return 0, err
	}
	t := now().UTC()
	mode, wait := poller.Decide(poller.Config{}, t, w.FixturesIn(st.Current), w.Gameweeks[st.Current], nil)
	if err := repo.SavePollState(ctx, stats.PollState{
		Mode: mode, Gameweek: st.Current, LastAttemptAt: t, LastGoodAt: t, NextPollAt: t.Add(wait),
	}); err != nil {
		return 0, err
	}
	return st.Current, nil
}

// createLeague creates the league, joins every manager, drafts and starts
// the season.
func createLeague(ctx context.Context, d Deps, userIDs []string) (string, error) {
	review := league.ReviewLeagueVote
	start := time.Date(2026, 8, 10, 19, 0, 0, 0, time.UTC)
	l, err := d.Leagues.Create(ctx, userIDs[0], LeagueName, len(Managers), Managers[0].Team,
		league.SettingsInput{TradeReview: &review, DraftStartsAt: &start})
	if err != nil {
		return "", err
	}
	inv, err := d.Leagues.CreateInvite(ctx, userIDs[0], l.ID, nil, nil)
	if err != nil {
		return "", err
	}
	for i, m := range Managers[1:] {
		if l, _, err = d.Leagues.AcceptInvite(ctx, userIDs[i+1], inv.Code, m.Team); err != nil {
			return "", err
		}
	}
	w, err := league.LoadWorld(ctx, d.Stats, -1)
	if err != nil {
		return "", err
	}
	var teamIDs []string
	for _, t := range l.Teams {
		teamIDs = append(teamIDs, t.ID)
	}
	g := &league.Game{Matchups: league.RoundRobin(teamIDs, l.Settings.StartGameweek, l.Settings.EndGameweek)}
	rosters := SnakeDraft(teamIDs, w.Players)
	now := d.Now().UTC().Truncate(time.Microsecond)
	for _, id := range teamIDs {
		for _, p := range rosters[id] {
			g.Rosters = append(g.Rosters, league.RosterSlot{TeamID: id, PlayerID: p, FromGW: 1, AcquiredVia: "draft"})
		}
		g.Lineups = append(g.Lineups, league.Lineup{TeamID: id, FromGW: 1, Slots: league.DefaultLineup(rosters[id], w.Players), UpdatedAt: now})
	}
	err = d.Leagues.Repo().Tx(ctx, func(tx league.Tx) error { return tx.StartSeason(ctx, l.ID, g) })
	return l.ID, err
}

// SnakeDraft drafts 15-man squads (2 GKP, 5 DEF, 5 MID, 3 FWD) in snake
// order: each pick is the best-ranked player left at a position the team
// still needs, as autopick does.
func SnakeDraft(teamIDs []string, players map[string]stats.Player) map[string][]string {
	pool := make([]stats.Player, 0, len(players))
	for _, p := range players {
		pool = append(pool, p)
	}
	slices.SortFunc(pool, func(a, b stats.Player) int {
		return cmp.Or(cmp.Compare(a.DraftRank, b.DraftRank), cmp.Compare(a.ID, b.ID))
	})
	need := map[string]scoring.Counts{}
	for _, id := range teamIDs {
		need[id] = scoring.Counts{}
		for pos, n := range scoring.StandardLineup().Squad {
			need[id][pos] = n
		}
	}
	taken := map[string]bool{}
	out := map[string][]string{}
	for round := 0; round < scoring.StandardLineup().SquadSize(); round++ {
		order := slices.Clone(teamIDs)
		if round%2 == 1 {
			slices.Reverse(order)
		}
		for _, team := range order {
			for _, p := range pool {
				if taken[p.ID] || need[team][p.Position] == 0 {
					continue
				}
				taken[p.ID] = true
				need[team][p.Position]--
				out[team] = append(out[team], p.ID)
				break
			}
		}
	}
	return out
}

// HistoryCodes are the demo players with recorded previous seasons
// (data/element-summary/{8,68,73,113}.json); 9000068 has none.
var HistoryCodes = []string{"9000008", "9000068", "9000073", "9000113"}

// LoadHistory saves the demo players' previous seasons through the real
// FPL decoder.
func LoadHistory(ctx context.Context, h history.Store, log *slog.Logger, now func() time.Time) error {
	f := &history.Fetcher{Source: Source(log), Store: h, Now: now, Log: log,
		Codes: func(context.Context) ([]string, error) { return slices.Clone(HistoryCodes), nil }}
	res, err := f.Run(ctx, time.Time{})
	if err == nil && res.Failed > 0 {
		err = fmt.Errorf("demo history: %d players failed", res.Failed)
	}
	return err
}
